-- Configuração de catálogo comercial existente; não altera schema nem assinaturas.
begin;
do $$ begin if (select count(*) from public.plans where slug in ('essencial','impulso','escala')) <> 3 then raise exception 'catalogo_incompleto'; end if; end $$;
update public.plans set price_monthly=10700, price_quarterly=29100, price_yearly=103200, min_attendants=2, features='["2 Números de WhatsApp","Caixa de entrada compartilhada","CRM Kanban","Fluxos de atendimento IA","Agentes IA","Base de conhecimento","Relatórios essenciais"]'::jsonb, limits=limits || '{"whatsapp":2,"pipelines":1,"sectors":1,"api":false,"campaigns":false,"agendamentos":false,"skills":false}'::jsonb where slug='essencial';
update public.plans set price_monthly=15900, price_quarterly=42900, price_yearly=152400, min_attendants=3, features='["Até 3 Números de WhatsApp","5 pipelines de vendas","Fluxos avançados e Agendamento","Campanhas em massa","Distribuição automática de leads","Agentes IA com processos","Skills para IA","API e Webhooks","Relatórios completos"]'::jsonb, limits=limits || '{"whatsapp":3,"pipelines":5,"sectors":3,"api":true,"campaigns":true,"agendamentos":true,"skills":true}'::jsonb where slug='impulso';
update public.plans set price_monthly=23400, price_quarterly=63300, price_yearly=224400, min_attendants=3, features='["WhatsApps ilimitados","Pipelines ilimitados","Distribuição avançada","Permissões avançadas","Logs e auditoria","Integrações avançadas para IA","Multiunidade e multimarca","API aberta para chat customizado","Atendimento Prime (VIP)"]'::jsonb, limits=limits || '{"whatsapp":-1,"pipelines":-1,"sectors":-1,"api":true,"campaigns":true,"agendamentos":true,"skills":true,"multiunit":true}'::jsonb where slug='escala';
commit;
select slug,price_monthly,price_quarterly,price_yearly,min_attendants,jsonb_array_length(features) as beneficios from public.plans order by price_monthly;
